function normalizeText(text) {
  return String(text)
    .toLocaleLowerCase('tr-TR')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const normalized = normalizeText(originalText);
const tokens = normalized.split(' ').filter(Boolean);

function containsPhrase(phrase) {
  return normalized.includes(normalizeText(phrase));
}

function tokenOverlap(words) {
  const normalizedWords = words.map(normalizeText);
  return normalizedWords.filter(word => tokens.includes(word)).length;
}

