function scoreIntent(intent) {
  let phraseMatches = 0;
  let tokenMatches = 0;

  const matchedPhrases = [];
  const matchedTokens = [];

  for (const phrase of intent.phrases) {
    if (containsPhrase(phrase)) {
      phraseMatches++;
      matchedPhrases.push(phrase);
    }
  }

  for (const token of intent.tokens) {
    const n = normalizeText(token);
    if (tokens.includes(n)) {
      tokenMatches++;
      matchedTokens.push(token);
    }
  }

  let score = 0;
  score += phraseMatches * 40;
  score += tokenMatches * 8;
  score += phraseMatches > 0 ? intent.priority / 10 : 0;

  return {
    ...intent,
    score,
    phraseMatches,
    tokenMatches,
    matchedPhrases,
    matchedTokens
  };
}

let ranked = intents
  .map(scoreIntent)
  .filter(item => item.score > 0)
  .sort((a, b) => {
    if (b.score !== a.score) return b.score - a.score;
    return b.priority - a.priority;
  });

if (!ranked.length) {
  ranked = [{
    id: 'general_concierge',
    label: 'General Concierge',
    priority: 40,
    agent: 'Concierge OS - General Concierge',
    actionMode: 'analyze_and_respond',
    requiredContext: ['memory', 'calendar'],
    score: 10,
    phraseMatches: 0,
    tokenMatches: 0,
    matchedPhrases: [],
    matchedTokens: []
  }];
}

const primary = ranked[0];
const secondaryCandidates = ranked
  .slice(1)
  .filter(item => item.score >= Math.max(16, primary.score * 0.35))
  .slice(0, 3);

const multiIntent = secondaryCandidates.length > 0;

let confidence = 0.45;
if (primary.phraseMatches >= 2) confidence = 0.99;
else if (primary.phraseMatches === 1 && primary.tokenMatches >= 2) confidence = 0.96;
else if (primary.phraseMatches === 1) confidence = 0.92;
else if (primary.tokenMatches >= 4) confidence = 0.90;
else if (primary.tokenMatches === 3) confidence = 0.84;
else if (primary.tokenMatches === 2) confidence = 0.76;
else if (primary.tokenMatches === 1) confidence = 0.62;

const ambiguityGap = ranked.length > 1 ? primary.score - ranked[1].score : primary.score;
const isAmbiguous = confidence < 0.70 || ambiguityGap < 8;

const safetyFlags = [];

if (/(satın al|odeme yap|pay now|book and pay|rezervasyon yap)/i.test(originalText)) {
  safetyFlags.push('external_transaction_requires_explicit_approval');
}

if (/(mesaj gonder|email gonder|send message|send email)/i.test(originalText)) {
  safetyFlags.push('external_communication_requires_explicit_approval');
}

if (/(sil|delete|cancel|iptal et)/i.test(originalText)) {
  safetyFlags.push('destructive_action_requires_explicit_approval');
}

const requiresApproval =
  primary.actionMode === 'prepare_and_request_approval' ||
  safetyFlags.length > 0;

const requestedAgentChain = [
  'Concierge OS - Memory Manager',
  'Concierge OS - Context Builder',
  primary.agent
];

for (const secondary of secondaryCandidates) {
  if (!requestedAgentChain.includes(secondary.agent)) {
    requestedAgentChain.push(secondary.agent);
  }
}

const contextAvailability = {
  userContext: Object.keys(userContext).length > 0,
  calendarContext: Object.keys(calendarContext).length > 0,
  activityHistory: Array.isArray(activityHistory) && activityHistory.length > 0,
  recommendationHistory: Array.isArray(recommendationHistory) && recommendationHistory.length > 0,
  feedbackHistory: Array.isArray(feedbackHistory) && feedbackHistory.length > 0
};

const missingContext = primary.requiredContext.filter(name => {
  if (name === 'memory') return !contextAvailability.userContext;
  if (name === 'calendar') return !contextAvailability.calendarContext;
  if (name === 'activity_history') return !contextAvailability.activityHistory;
  if (name === 'recommendation_history') return !contextAvailability.recommendationHistory;
  if (name === 'feedback_history') return !contextAvailability.feedbackHistory;
  if (name === 'weather') return !input.weatherContext;
  return false;
});

const plan = {
  primaryIntent: primary.id,
  secondaryIntents: secondaryCandidates.map(item => item.id),
  multiIntent,
  steps: [
    {
      order: 1,
      workflow: 'Concierge OS - Memory Manager',
      purpose: 'Load persistent user profile and preferences'
    },
    {
      order: 2,
      workflow: 'Concierge OS - Context Builder',
      purpose: 'Combine memory, calendar, history and live request context'
    },
    {
      order: 3,
      workflow: primary.agent,
      purpose: `Handle primary intent: ${primary.label}`
    }
  ]
};

secondaryCandidates.forEach((item, index) => {
  plan.steps.push({
    order: 4 + index,
    workflow: item.agent,
    purpose: `Handle secondary intent: ${item.label}`
  });
});

return [{
  json: {
    success: true,
    engineVersion: '2.0.0',
    request: {
      originalText,
      normalizedText: normalized,
      tokens
    },
    decision: {
      primaryIntent: primary.id,
      primaryLabel: primary.label,
      primaryAgent: primary.agent,
      actionMode: primary.actionMode,
      confidence,
      isAmbiguous,
      multiIntent,
      requiresApproval,
      safetyFlags,
      requiredContext: primary.requiredContext,
      missingContext
    },
    routing: {
      requestedAgentChain,
      secondaryAgents: secondaryCandidates.map(item => item.agent)
    },
    plan,
    evidence: {
      matchedPhrases: primary.matchedPhrases,
      matchedTokens: primary.matchedTokens,
      primaryScore: primary.score,
      ambiguityGap,
      alternatives: ranked.slice(1, 5).map(item => ({
        intent: item.id,
        label: item.label,
        agent: item.agent,
        score: item.score,
        matchedPhrases: item.matchedPhrases,
        matchedTokens: item.matchedTokens
      }))
    },
    contextAvailability
  }
}];
